import { useParallax } from '../../../hooks/useParallax';
import { getIsolatedParallaxProps } from '../../../helpers/getIsolatedParallaxProps';
import { getExpandedStyle } from '../helpers/getExpandedStyle';
import { getImageStyle } from '../helpers/getImageStyle';
import { BannerLayer } from '../types';

const absoluteStyle: CSSProperties = {
  position: 'absolute',
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
};

export const ParallaxBannerLayer = (
  props: BannerLayer & { testId?: string }
) => {
  const { parallaxProps, rest } = getIsolatedParallaxProps(props);
  const {
    children,
    disabled,
    style,
    expanded = true,
    image,
    testId,
    ...divProps
  } = rest;

  const imageStyle = getImageStyle(props);
  const expandedStyle = expanded ? getExpandedStyle(props) : {};
  const parallax = useParallax<HTMLDivElement>({
    targetElement: props.targetElement,
    shouldDisableScalingTranslations: true,
    ...parallaxProps,
  });

  return (
    <div
      data-testid={testId}
      ref={parallax.ref}
      style={{
        ...imageStyle,
        ...absoluteStyle,
        ...expandedStyle,
        ...style,
      }}
      {...divProps}
    >
      {rest.children}
    </div>
  );
};
import React, {
  PropsWithChildren,
  CSSProperties,
  useEffect,
  useRef,
  useState,
  ReactElement,
} from 'react';
import { ParallaxBannerLayer } from './components/ParallaxBannerLayer';
import { ParallaxBannerProps } from './types';

const containerStyle: CSSProperties = {
  position: 'relative',
  overflow: 'hidden',
  width: '100%',
};

export const ParallaxBanner = (
  props: PropsWithChildren<ParallaxBannerProps>
) => {
  const [targetElement, setTargetElement] =
    useState<HTMLDivElement | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    setTargetElement(containerRef.current);
  }, []);
  const {
    disabled: disableAllLayers,
    style: rootStyle,
    layers = [],
    ...rootRest
  } = props;

  function renderLayers() {
    if (targetElement) {
      const shouldUseLayers = layers && layers.length > 0;
      if (shouldUseLayers) {
        return layers.map((layer, i) => (
          <ParallaxBannerLayer
            {...layer}
            targetElement={targetElement}
            key={`layer-${i}`}
            testId={`layer-${i}`}
          />
        ));
      }
    }
    return null;
  }

  function renderChildren() {
    if (targetElement) {
      return React.Children.map(props.children, (child) => {
        const item = child as ReactElement<
          PropsWithChildren<{ targetElement: any }>
        >;
        // adds the targetElement prop to any ParallaxBannerLayer components
        if (item?.type === ParallaxBannerLayer) {
          const clone = React.cloneElement(item, {
            targetElement,
          });
          return clone;
        }
        return child;
      });
    }
    return null;
  }
  return (
    <div
      ref={containerRef}
      style={{ ...containerStyle, ...rootStyle }}
      {...rootRest}
    >
      {/* Using the `layers` prop to define children */}
      {renderLayers()}
      {/* Using children to compose layers */}
      {renderChildren()}
    </div>
  );
};
import {
  ParallaxController,
  ParallaxControllerOptions,
} from 'parallax-controller';

export const createController = (options: ParallaxControllerOptions) => {
  // Don't initialize on the server
  const isServer = typeof window === 'undefined';

  if (!isServer) {
    // Must not be the server so kick it off...
    return ParallaxController.init(options);
  }
  return null;
};
import React, { PropsWithChildren, useEffect, useRef } from 'react';

import { ParallaxContext } from '../../context/ParallaxContext';
import { ParallaxController, ScrollAxis } from 'parallax-controller';
import { ParallaxProviderProps } from './types';
import { createController } from './helpers';

export function ParallaxProvider(
  props: PropsWithChildren<ParallaxProviderProps>
) {
  const controller = useRef<null | ParallaxController>(null);

  if (!controller.current) {
    controller.current = createController({
      scrollAxis: props.scrollAxis || ScrollAxis.vertical,
      scrollContainer: props.scrollContainer,
      disabled: props.isDisabled,
    });
  }

  // update scroll container
  useEffect(() => {
    if (props.scrollContainer && controller.current) {
      controller.current.updateScrollContainer(props.scrollContainer);
    }
  }, [props.scrollContainer]);

  // disable/enable parallax
  useEffect(() => {
    if (props.isDisabled && controller.current) {
      controller.current.disableParallaxController();
    }
    if (!props.isDisabled && controller.current) {
      controller.current.enableParallaxController();
    }
  }, [props.isDisabled]);

  // remove the controller when unmounting
  useEffect(() => {
    return () => {
      controller?.current?.destroy();
    };
  }, []);

  return (
    <ParallaxContext.Provider value={controller.current}>
      {props.children}
    </ParallaxContext.Provider>
  );
}
